import { uniqueStrings } from './unique_changed.mjs';

// Basic dedup with case differences
const input = ['Apple', 'apple', 'BANANA', 'banana', 'Cherry', 'APPLE'];
const out = uniqueStrings(input);
console.log('out:', JSON.stringify(out));
console.assert(JSON.stringify(out) === JSON.stringify(['Apple', 'BANANA', 'Cherry']), 'case dedup failed');

// Original order preserved, first occurrence kept
const input2 = ['b', 'A', 'a', 'B', 'c'];
const out2 = uniqueStrings(input2);
console.log('out2:', JSON.stringify(out2));
console.assert(JSON.stringify(out2) === JSON.stringify(['b', 'A', 'c']), 'order/first-occurrence failed');

// Whitespace not trimmed
const input3 = [' x ', 'x', ' x '];
const out3 = uniqueStrings(input3);
console.log('out3:', JSON.stringify(out3));
console.assert(JSON.stringify(out3) === JSON.stringify([' x ', 'x']), 'whitespace handling failed');

// Input not mutated
const input4 = ['Foo', 'foo', 'Bar'];
const snapshot = [...input4];
uniqueStrings(input4);
console.assert(JSON.stringify(input4) === JSON.stringify(snapshot), 'input was mutated');

// Empty array
console.assert(JSON.stringify(uniqueStrings([])) === '[]', 'empty array failed');

// Non-ASCII unaffected (toLowerCase still applied)
const input5 = ['É', 'é', 'E'];
const out5 = uniqueStrings(input5);
console.log('out5:', JSON.stringify(out5));

console.log('All checks passed.');
"

